def count_partitions(n, k):
    if n < 0 or k < 0:
        return 0
    if k == 0:
        return 1 if n == 0 else 0
    if k > n:
        return 0
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, min(k, i) + 1):
            dp[i][j] = dp[i - 1][j - 1] + (dp[i - j][j] if i - j >= 0 else 0)
    return dp[n][k]

def is_palindrome_base(n, b):
    if n == 0:
        return True
    digits = []
    x = n
    while x > 0:
        digits.append(x % b)
        x //= b
    return digits == digits[::-1]

def digit_sum_base(n, b):
    if n == 0:
        return 0
    s = 0
    while n > 0:
        s += n % b
        n //= b
    return s

def fibonacci_mod(n, m):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, (a + b) % m
    return a % m

def count_digit_sum_in_range(low, high, s):
    count = 0
    for x in range(low, high + 1):
        if sum(int(d) for d in str(x)) == s:
            count += 1
    return count

def integer_sqrt_floor(n):
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

